import Fastify from "fastify";

export const app = Fastify({ logger: false });

const productSchema = {
  type: "object",
  required: ["name", "price"],
  properties: {
    name: { type: "string" },
    price: { type: "number" },
  },
};

app.post("/products", { schema: { body: productSchema } }, async function createProduct(request, reply) {
  return reply.status(201).send(request.body);
});
